/// @notice Vault state struct
struct VaultState {
    /// @dev Total assets held in the vault
    uint256 totalAssets;
    /// @dev Total shares issued by the vault
    uint256 totalShares;
    /// @dev Mapping of account addresses to their share balances in the vault
